-- preludes: ["sim-helpers.js", "trial-helpers.js"]
mem.world = await sim.world({seed: 7})            -- seed on mem so a trial is repeatable
mem.bodies = (await mem.world.spawn(specs)).map(b => b.id)
for (s of [0.5, 1, 2, 4]) {
  await mem.world.step(to: s)
  mem.series.push({ t: s, ...await mem.world.sensors(mem.bodies) })
}
return mem.world.sheet(mem.series.map(s => s.t))  -- frames attach via .look("t=...")
